const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

async function main() {
  const ledger = new Ledger();
  const acknowledged = [];
  const service = new PaymentService(ledger, {
    acknowledge: async receipt => { acknowledged.push(receipt); },
  });
  const receipts = await Promise.all(Array.from({ length: 10 }, () => service.pay('a', 'key', 100)));
  assert.equal(ledger.entries.length, 1);
  receipts.forEach(receipt => assert.equal(receipt, receipts[0]));
  assert.equal(await service.pay('a', 'key', 100), receipts[0]);
  await assert.rejects(service.pay('a', 'key', 101), { message: 'key conflict' });
  assert.equal(acknowledged.length, 11);
  assert.equal(ledger.entries.length, 1);
  await service.pay('b', 'key', 101);
  await service.pay('a', 'other', 101);
  assert.equal(ledger.entries.length, 3);

  // Tuple keys must not collide when tenant/key contain separators.
  await ledger.apply('a:b', 'c', 1);
  await ledger.apply('a', 'b:c', 2);
  assert.equal(ledger.entries.length, 5);
  const conflicting = await Promise.allSettled([
    ledger.apply('concurrent', 'key', 1), ledger.apply('concurrent', 'key', 2),
  ]);
  assert.equal(conflicting[0].status, 'fulfilled');
  assert.equal(conflicting[1].reason.message, 'key conflict');
  assert.equal(ledger.entries.length, 6);

  for (const attempts of [1, 3, 5]) {
    const retryLedger = new Ledger();
    const seen = [];
    const errors = Array.from({ length: attempts }, () => new Transient('retry'));
    const retryService = new PaymentService(retryLedger, {
      acknowledge: async receipt => { seen.push(receipt); throw errors[seen.length - 1]; },
    });
    await assert.rejects(retryService.pay('a', 'key', 100, attempts), error => error === errors.at(-1));
    assert.equal(seen.length, attempts);
    assert.equal(retryLedger.entries.length, 1);
    seen.forEach(receipt => assert.equal(receipt, seen[0]));
  }
  const successLedger = new Ledger();
  const seen = [];
  const retrySuccess = new PaymentService(successLedger, {
    acknowledge: async receipt => { seen.push(receipt); if (seen.length < 3) throw new Transient(); },
  });
  assert.equal(await retrySuccess.pay('a', 'key', 100), seen[0]);
  assert.equal(seen.length, 3);
  assert.equal(successLedger.entries.length, 1);
  seen.forEach(receipt => assert.equal(receipt, seen[0]));

  let calls = 0;
  const fatal = new Error('fatal');
  const fatalService = new PaymentService(new Ledger(), {
    acknowledge: async () => { calls++; throw fatal; },
  });
  await assert.rejects(fatalService.pay('a', 'key', 100), error => error === fatal);
  assert.equal(calls, 1);

  const validationService = new PaymentService({ apply: async () => { throw new Error('ledger called'); } }, {
    acknowledge: async () => { throw new Error('transport called'); },
  });
  for (const args of [
    ['', 'k', 1], ['t', '', 1], [null, 'k', 1], ['t', 1, 1],
    ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', NaN],
    ...[0, -1, 6, 1.5, NaN, Infinity, null, '3'].map(n => ['t', 'k', 1, n]),
  ]) {
    await assert.rejects(validationService.pay(...args), { message: 'invalid payment' });
  }
  const invalidLedger = new Ledger();
  await assert.rejects(invalidLedger.apply('', 'k', 1), { message: 'invalid payment' });
  assert.equal(invalidLedger.entries.length, 0);
}
main().catch(error => { console.error(error); process.exitCode = 1; });

